message.content:
{
  "candidate_edge_types": [
    {
      "name": "PROVISIONS_MISSING_PREREQUISITE",
      "definition": "A subsequent agent action installs, creates, or otherwise provides a required component that an earlier diagnostic observation reported as absent or unavailable.",
      "source_description": "An observation from a diagnostic/probe step reporting that a required component (tool, account, service, or dependency) is missing.",
      "target_description": "A subsequent agent action that installs or provisions the missing component so it becomes available."
    },
    {
      "name": "VERIFIES_EFFECT_OF_PRIOR_ACTION",
      "definition": "A subsequent check is executed to determine whether an earlier configuration or execution action actually produced its intended effect.",
      "source_description": "An earlier action whose outcome or effect is uncertain and needs to be confirmed.",
      "target_description": "A subsequent check or probe command executed to observe the effect of that earlier action."
    },
    {
      "name": "REVERTS_SIDE_EFFECTS_TO_RESTORE_PRECONDITION",
      "definition": "A subsequent action undoes state changes left behind by an earlier test or trial run in order to restore a precondition required by the intended workflow.",
      "source_description": "An earlier test or trial action that produced persistent state changes as a side effect.",
      "target_description": "A subsequent action that reverts or cleans up those state changes to restore the original precondition."
    },
    {
      "name": "CONCLUDES_COMPLETION_FROM_VERIFIED_STATE",
      "definition": "A task-completion decision is made on the basis of a preceding verification that confirmed the final state satisfies the task requirements.",
      "source_description": "A verification result confirming that the final environment state matches the required configuration.",
      "target_description": "A task-completion decision or completion signal derived from that verification."
    },
    {
      "name": "AUDITS_FOR_OVERLOOKED_PREREQUISITE_AFTER_COMPLETION_INTENT",
      "definition": "After expressing intent to finalize the task, the agent performs an additional diagnostic examination of the environment to detect a required component or prerequisite that may have been overlooked before finalization.",
      "source_description": "An initial task-completion decision or intent to finalize.",
      "target_description": "A subsequent diagnostic probe of the environment performed to reveal overlooked prerequisites."
    }
  ]
}

